-- Verify what landed:
SELECT (SELECT code FROM properties WHERE id=s."propertyId") AS property,
       to_char(date_trunc('month', "snapshotDate"), 'YYYY-MM') AS snap_month,
       count(DISTINCT "snapshotDate") AS days, count(*) AS rows
FROM daily_pickup_snapshots s GROUP BY 1,2 ORDER BY 1,2;
